// Question bank. Correct answers are stored apart from wrong answers; engine.js
// assigns answer positions at render time.
//
// Anti-guessing rules (checked by tests/slots.test.js):
// - Options in a set are written to similar lengths, and the correct answer is
//   the longest, the shortest, or in between about equally often.
// - Absolute words (always, never, only, every, all) appear in correct and
//   wrong answers at about the same rate, so "absolutes are wrong" fails.
// - Wrong answers are real misconceptions, not jokes.

let n = 0;
const nid = (p) => `${p}-${++n}`;

function mc(req, q, correct, wrong, why, jt) {
  return { id: nid(req), req, type: "mc", q, correct, wrong, why, jt };
}
function tier(req, q, correct, wrong, bq, bcorrect, bwrong, why, jt) {
  return { id: nid(req), req, type: "tier", q, correct, wrong, bq, bcorrect, bwrong, why, jt };
}
function order(req, q, steps, why) {
  return { id: nid(req), req, type: "order", q, steps, why };
}
function match(req, q, pairs, why) {
  return { id: nid(req), req, type: "match", q, pairs, why };
}
function odd(req, q, oddOne, others, bcorrect, bwrong, why) {
  return { id: nid(req), req, type: "odd", q, oddOne, others, bcorrect, bwrong, why };
}

